import{_ as a,H as e,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"加餐 | Exporter生态太过零散，如何整合？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Exporter 因何崛起","slug":"exporter-因何崛起","link":"#exporter-因何崛起","children":[]},{"level":2,"title":"Exporter 的问题","slug":"exporter-的问题","link":"#exporter-的问题","children":[]},{"level":2,"title":"Cprobe 简介","slug":"cprobe-简介","link":"#cprobe-简介","children":[]},{"level":2,"title":"Cprobe 安装","slug":"cprobe-安装","link":"#cprobe-安装","children":[{"level":3,"title":"Cprobe 监控 MySQL","slug":"cprobe-监控-mysql","link":"#cprobe-监控-mysql","children":[]},{"level":3,"title":"Cprobe 监控 Redis","slug":"cprobe-监控-redis","link":"#cprobe-监控-redis","children":[]},{"level":3,"title":"Cprobe 监控 MongoDB","slug":"cprobe-监控-mongodb","link":"#cprobe-监控-mongodb","children":[]},{"level":3,"title":"Cprobe 监控 Oracle","slug":"cprobe-监控-oracle","link":"#cprobe-监控-oracle","children":[]},{"level":3,"title":"Cprobe 监控 Postgres","slug":"cprobe-监控-postgres","link":"#cprobe-监控-postgres","children":[]},{"level":3,"title":"Cprobe 监控 Tomcat","slug":"cprobe-监控-tomcat","link":"#cprobe-监控-tomcat","children":[]},{"level":3,"title":"Cprobe 监控 Kafka","slug":"cprobe-监控-kafka","link":"#cprobe-监控-kafka","children":[]},{"level":3,"title":"Cprobe 监控 ElasticSearch","slug":"cprobe-监控-elasticsearch","link":"#cprobe-监控-elasticsearch","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"运维监控系统实战笔记/加餐｜Exporter生态太过零散，如何整合？.md","filePath":"运维监控系统实战笔记/加餐｜Exporter生态太过零散，如何整合？.md","lastUpdated":1795561216000}'),t={name:"运维监控系统实战笔记/加餐｜Exporter生态太过零散，如何整合？.md"};function l(i,s,o,r,c,E){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="加餐-exporter生态太过零散-如何整合" tabindex="-1">加餐 | Exporter生态太过零散，如何整合？ <a class="header-anchor" href="#加餐-exporter生态太过零散-如何整合" aria-label="Permalink to &quot;加餐 | Exporter生态太过零散，如何整合？&quot;">​</a></h1><p>你好，我是秦晓辉。</p><p>上一节我们对比了 Zabbix 和 Prometheus 的设计理念，在数据采集方面 Prometheus 依靠了庞大的社区力量缔造了 Exporter 生态。这节课我们就围绕 Exporter 来聊一聊，看看 Exporter是因何崛起，有什么问题，以及如何解决。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/1.png" alt=""></a></p><h2 id="exporter-因何崛起" tabindex="-1">Exporter 因何崛起 <a class="header-anchor" href="#exporter-因何崛起" aria-label="Permalink to &quot;Exporter 因何崛起&quot;">​</a></h2><p>纵观国际可观测性头部厂商，比如 Datadog、Dynatrace、NewRelic，他们都有自己的 all-in-one 的 agent，可见大家普遍认为这是一个最佳实践。开源社区也有类似的项目，就是Telegraf、Categraf。但是企业要真正落地的时候，很多公司还是在使用各种零散的Exporter。原因何在？我感觉主要是因为如下几点。</p><ul><li><p>Exporter 的生态更好，包括各类文档、博客、分享，以及 Exporter 对应的 GrafanaDashboard；</p></li><li><p>Prometheus 主推的就是 Exporter，用户接触这个生态肯定是从 Prometheus 官网文档开始，被引导去使用 Exporter 也是理所当然。而一旦用起来了，再换就有迁移成本了；</p></li><li><p>Exporter 是开源集市的玩法，普通技术人员很容易做一个 Exporter，既满足自己的需求也建立了个人品牌。同时又因为是自己的需求驱动，Exporter 的研发人员对相关数据如何采集、哪些数据更为关键，相对更熟悉，做出来的 Exporter 也就更实用。</p></li></ul><p>当然，可能还有其他因素我暂未想到，欢迎你在评论区发表自己的看法。当然了，凡事没有尽善尽美，在落地 Exporter 的过程中，我们也会遇到一些问题。</p><h2 id="exporter-的问题" tabindex="-1">Exporter 的问题 <a class="header-anchor" href="#exporter-的问题" aria-label="Permalink to &quot;Exporter 的问题&quot;">​</a></h2><p>由于 Exporter 是不同的人开发的，其代码风格、配置方式、使用体验都有较大差别，比如下面这些。</p><ul><li><p>有的 Exporter 采用命令行参数的方式来控制 Exporter 的行为，另一些则是采用配置文件，而且不同的 Exporter 其配置文件的格式各异；</p></li><li><p>日志打印方式各异，有的是打印到标准输出有的是打印到日志文件，日志级别定义的方式也不尽相同；</p></li><li><p>有的 Exporter 是一对一的设计（即一个 Exporter 采集一个目标实例），而有的 Exporter 是一对多的设计（即一个 Exporter 可以采集多个目标实例）。</p></li></ul><p>那么有没有可能把众多的 Exporter 整合在一起，类似各大头部厂商做的那样，搞成一个统一</p><p>的 agent 呢？这样使用体验既可以趋于一致且维护方便，也不用部署很多采集器进程，从而节省了机器资源。</p><p>其实确实已经有厂商这么做了，比如 GrafanaLabs 的 Grafana-agent，不过 Grafana-agent后来放弃维护，转头去做 OTel 发行版了，比较可惜。</p><p>我也做了一个这样的开源项目，纯粹为了自己方便，叫 Cprobe。如果你也有类似诉求，可以来一起完善这个项目。借助专栏加餐的方式，给你分享一下我的一些设计逻辑以及基本用法，希望对你有所启发和帮助。</p><h2 id="cprobe-简介" tabindex="-1">Cprobe 简介 <a class="header-anchor" href="#cprobe-简介" aria-label="Permalink to &quot;Cprobe 简介&quot;">​</a></h2><p>Cprobe 算是一个缝合怪，把众多 Exporter 缝合在一起，尝试解决零散 Exporter 的问题，关键设计逻辑和目标如下。</p><ul><li><p>直接把 Exporter 作为 lib 库 import 进来，避免 Exporter 频繁迭代导致 Cprobe patch 滞后，如果原本 Exporter 的写法没法支持 import，则把代码拷贝过来，尽量不修改原本的代码，这样后面改动方便；</p></li><li><p>集成代码的时候，使用统一的日志库来替代各个 Exporter 原本的日志库，可以确保日志格式统一、级别统一、日志打印到统一的文件；</p></li><li><p>统一配置方式，把各个 Exporter 原本的配置方式全部改成配置文件的方式，使用尽可能一致的配置格式，让体验一致；</p></li><li><p>把采集方式统一为一对多的方式，比如 Cprobe 的 MySQL 插件，可以同时采集多个MySQL 实例；Cprobe 的 Redis 插件，可以同时采集多个 Redis 实例；</p></li><li><p>配置文件支持复用，因为同类实例可以采集多个，每个实例的采集配置很有可能是类似甚至相同的，这就需要做到配置复用，类似配置文件 include 机制；</p></li><li><p>支持服务发现，即类似 Prometheus 的 SD 机制，自动发现目标实例，至少支持 Static、File、HTTP、Kubernetes 这几种 SD 方式；</p></li><li><p>不但提供采集能力，还要尽可能提供开箱即用的 Grafana 仪表盘和告警规则，把最佳实践</p></li><li><p>沉淀下来。</p></li></ul><p>你可以点击超链接跳转项目地址，项目 License 采用 AGPL-3.0 开源协议。通过社区各位Contributor 通力合作，目前已经集成了 MySQL、Redis、Kafka、Oracle、DM8 等 18 个Exporter 插件，涵盖了常见的中间件、数据库，上面提到的设计目标也基本完成，下面我来做个实操演示，助你快速上手。</p><h2 id="cprobe-安装" tabindex="-1">Cprobe 安装 <a class="header-anchor" href="#cprobe-安装" aria-label="Permalink to &quot;Cprobe 安装&quot;">​</a></h2><p>到 Cprobe 的 releases 页面下载发布包。解包之后可以看到二进制 cprobe，可以通过如下命令安装。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --install</span></span></code></pre></div><p>如果是支持 systemd 的 OS，上面的安装过程实际就是自动创建了 service 文件，你可以通过下面的命令查看。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>systemctl status cprobe</span></span></code></pre></div><p>Cprobe 需要配置正确的 remote write 地址才能正常启动，作为一个采集器，Cprobe 采集了数据要推给时序库，推送协议是 remote write 协议，后端时序库的地址配置在conf.d/writer.yaml，样例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> extra_labels:</span></span>
<span class="line"><span>   colld: cprobe</span></span>
<span class="line"><span>writers:</span></span>
<span class="line"><span>- url: http://127.0.0.1:8428/api/v1/write</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>writers  是个数组，可以配置多个后端时序库地址，extra_labels 是附加标签，会附加到所</span></span></code></pre></div><p>有采集的数据上，一般不用配置。当然，还支持 metric_relabel_configs 等 relabel 配置，查看</p><p>配置样例即可，这里就不赘述了。</p><p>上例中的 url 样例，其端口是 8428，这是 VictoriaMetrics 单机版的默认端口，我建议新项目在选型时序库的时候，用 VictoriaMetrics 就可以了。如果是 Prometheus 作为后端时序库，默认端口改成 9090，另外 Prometheus 默认是不开 remote write receiver 的，需要通过命令行参数开启。</p><p>配置好了 remote write 地址就可以启动 Cprobe 了，可以通过如下命令启动。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --start</span></span></code></pre></div><p>如果是支持 systemd 的 OS，Cprobe 默认交给 systemd 托管，所以也可以直接使用systemctl 来启动。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>systemctl start cprobe</span></span>
<span class="line"><span>如果要开机自启动，记得要  systemctl enable cprobe 来 Enable 一下 Cprobe 服务。</span></span></code></pre></div><p>Cprobe 也是插件机制，我们以 MySQL 举例，讲解一下其配置方法，其他插件都是类似的。</p><h3 id="cprobe-监控-mysql" tabindex="-1">Cprobe 监控 MySQL <a class="header-anchor" href="#cprobe-监控-mysql" aria-label="Permalink to &quot;Cprobe 监控 MySQL&quot;">​</a></h3><p>每个插件一个配置目录，每个目录中都有一个入口配置叫 main.yaml，MySQL 插件的入口配置自然就是 conf.d/mysql/main.yaml ，下面是一个样例。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   cplugin: &#39;mysql&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;mysql_static&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - &#39;127.0.0.1:3306&#39;</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule_head.toml&#39;</span></span>
<span class="line"><span> - &#39;rule_coll.toml&#39;</span></span>
<span class="line"><span>- job_name: &#39;mysql_http_sd&#39;</span></span>
<span class="line"><span> http_sd_configs:</span></span>
<span class="line"><span> - url: http://localhost:8080/get-targets</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule_head.toml&#39;</span></span>
<span class="line"><span> - &#39;rule_coll.toml&#39;</span></span>
<span class="line"><span>- job_name: &#39;mysql_file_sd&#39;</span></span>
<span class="line"><span> file_sd_configs:</span></span>
<span class="line"><span> - files:</span></span>
<span class="line"><span>   - &#39;inst.yaml&#39;</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule_head.toml&#39;</span></span>
<span class="line"><span> - &#39;rule_coll.toml&#39;</span></span>
<span class="line"><span> - &#39;rule_cust.toml&#39;</span></span></code></pre></div><p>整体配置和 Prometheus 的抓取配置特别像。global 部分配置全局抓取频率以及插件级别的全局附加标签（可以没有），scrape_configs 是抓取目标，支持 static、http_sd、file_sd，暂不支持 Kubernetes SD，scrape_rule_files 是一个比较有意思的配置，定义详细的采集规则，这是个数组，程序处理时会把数组里的每个规则文件拼接成一个整体来使用，通过这种方式可以实现配置文件拆分管理和复用。</p><p>假设你有两组 MySQL 实例，认证方式不同，就可以创建两个配置文件只存储认证信息，比如rule_head1.toml 的内容如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[global]</span></span>
<span class="line"><span>user = &#39;cprobe1&#39;</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>password = &#39;1234&#39;</span></span></code></pre></div><p>rule_head2.toml 的内容如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[global]</span></span>
<span class="line"><span>user = &#39;cprobe2&#39;</span></span>
<span class="line"><span>password = &#39;5678&#39;</span></span></code></pre></div><p>然后把这两组 MySQL 实例使用两个 job 来抓取，第一个 job 引用 rule_head1.toml，第二个job 引用 rule_head2.toml，剩下的采集配置项都相同，可以放到 rule_coll.toml 中。然后两个job 都引用 rule_coll.toml，以此做到配置拆分和复用。</p><p>rule_coll.toml 中的内容较多，你可能不知道是什么意思，其实就是把 mysqld_exporter 的命令行配置转成了 toml 格式的配置，至于每个配置项具体含义，可以参考 mysqld_exporter 的文档。Cprobe 每个插件下面通常都有一个 doc 目录，里边有个 README.md 会介绍这个插件 fork 自哪里，doc 目录里的 alerts 目录（如有）存放的是这个插件相关的告警规则，dash目录（如有）存放的是这个插件相关的仪表盘。</p><p>MySQL 采集规则配置好了可以通过如下命令测试。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins mysql</span></span>
<span class="line"><span>相关参数的解释可以参考  ./cprobe --help 的信息，这里我重复解释一下。</span></span>
<span class="line"><span>--no-writer 表示当前启动 Cprobe 进程时不推送监控数据到远端时序库，仅仅打印到控</span></span></code></pre></div><ul><li>制台，通常测试的时候是这么用；</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--no-httpd 表示当前启动 Cprobe 进程不监听 HTTP 端口，Cprobe 默认会监听 HTTP</span></span></code></pre></div><ul><li>端口 5858，用处不大，就是暴露了一个健康检查的页面。如果当前已经有一个 Cprobe 在运行了，我们测试 MySQL 插件的时候就要加上这个参数，防止报重复绑定端口的错误；</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--plugins mysql 是指定只运行 mysql 这个插件。</span></span></code></pre></div><p>如果上面的命令输出一堆 MySQL 监控指标，就说明采集成功。然后我们重启 Cprobe 进程，稍等片刻 Cprobe 就会把采集的数据写到时序库中。然后我们把 conf.d/mysql/doc/dash 下面的仪表盘导入 Grafana，效果如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/2.png" alt=""></a></p><p>其他插件的配置方式和 MySQL 类似，我再举几个例子。</p><h3 id="cprobe-监控-redis" tabindex="-1">Cprobe 监控 Redis <a class="header-anchor" href="#cprobe-监控-redis" aria-label="Permalink to &quot;Cprobe 监控 Redis&quot;">​</a></h3><p>Redis 的插件配置在 conf.d/redis 下面，main.yaml 举例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span>
<span class="line"><span>   cplugin: &#39;redis&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;redis&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - &#39;10.99.1.107:6379&#39;</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule.toml&#39;</span></span></code></pre></div><p>通过如下命令可以测试是否采集成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins redis</span></span></code></pre></div><p>只要输出一堆 Redis 指标就说明采集正常，重启 Cprobe 稍等片刻就可以在时序库查到 Redis相关的监控数据了，仪表盘样例如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/3.png" alt=""></a></p><h3 id="cprobe-监控-mongodb" tabindex="-1">Cprobe 监控 MongoDB <a class="header-anchor" href="#cprobe-监控-mongodb" aria-label="Permalink to &quot;Cprobe 监控 MongoDB&quot;">​</a></h3><p>MongoDB 的插件配置在 conf.d/mongodb 下面，main.yaml 举例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span>
<span class="line"><span>   cplugin: &#39;mongodb&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;standalone&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - 10.99.1.110:27017</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule.toml&#39;</span></span></code></pre></div><p>如果有认证信息，可以在 conf.d/mongodb/rule.toml 中配置，如果不同的 MongoDB 认证信息不同，可以类似 MySQL 那样拆分配置文件，通过如下命令可以测试采集是否成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins mongodb</span></span></code></pre></div><p>只要输出一堆 MongoDB 指标就说明采集正常，重启 Cprobe 稍等片刻就可以在时序库查到MongoDB 相关的监控数据了，仪表盘样例如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/4.png" alt=""></a></p><h3 id="cprobe-监控-oracle" tabindex="-1">Cprobe 监控 Oracle <a class="header-anchor" href="#cprobe-监控-oracle" aria-label="Permalink to &quot;Cprobe 监控 Oracle&quot;">​</a></h3><p>Oracle 的插件配置在 conf.d/oracledb 下面，main.yaml 举例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span>
<span class="line"><span>   cplugin: &#39;oracle&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;oracle&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - 10.99.1.107:1521/xe # ip:port/service</span></span>
<span class="line"><span> scrape_rule_files:</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> - &#39;link.toml&#39;</span></span>
<span class="line"><span> - &#39;comm.toml&#39;</span></span></code></pre></div><p>一般监控目标，即 target 的配置都是 IP + 端口，Oracle 的略有不同，需要配置成 IP + 端口 +service，上例中的 xe 就是 service。通过如下命令可以测试采集是否成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins oracledb</span></span></code></pre></div><p>只要输出一堆 Oracle 指标就说明采集正常，重启 Cprobe 稍等片刻就可以在时序库查到Oracle 相关的监控数据了，仪表盘样例如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/5.png" alt=""></a></p><h3 id="cprobe-监控-postgres" tabindex="-1">Cprobe 监控 Postgres <a class="header-anchor" href="#cprobe-监控-postgres" aria-label="Permalink to &quot;Cprobe 监控 Postgres&quot;">​</a></h3><p>Postgres 的插件配置在 conf.d/postgres 下面，main.yaml 举例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>   cplugin: &#39;postgres&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;postgres&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - &#39;10.99.1.107:15432&#39;</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule.toml&#39;</span></span></code></pre></div><p>通过如下面命令可以测试是否采集成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins postgres</span></span></code></pre></div><p>只要输出一堆 Postgres 指标就说明采集正常，重启 Cprobe 稍等片刻就可以在时序库查到Postgres 相关的监控数据了，仪表盘样例如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/6.png" alt=""></a></p><h3 id="cprobe-监控-tomcat" tabindex="-1">Cprobe 监控 Tomcat <a class="header-anchor" href="#cprobe-监控-tomcat" aria-label="Permalink to &quot;Cprobe 监控 Tomcat&quot;">​</a></h3><p>Tomcat 的插件配置在 conf.d/tomcat 下面，依旧是 main.yaml 举例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span>
<span class="line"><span>   cplugin: &#39;tomcat&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;tomcat&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - &#39;10.211.55.3:8080&#39;</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule.toml&#39;</span></span></code></pre></div><p>这里注意，Tomcat 监控需要修改 conf/tomcat-users.xml 配置，增加 role 和 user，比如下面这样。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​tomcat-users xmlns=&quot;http://tomcat.apache.org/xml&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             xmlns:xsi=&quot;http://www.w3.org/2001/XMLSchema-instance&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             xsi:schemaLocation=&quot;http://tomcat.apache.org/xml tomcat-users.xsd&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">             version=&quot;1.0&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;​role rolename=&quot;manager-gui&quot;/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt;​user username=&quot;tomcat&quot; password=&quot;s3cret&quot; roles=&quot;manager-gui&quot;/&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​/tomcat-users&gt;</span></span></code></pre></div><p>其次，通常 Cprobe 和 Tomcat 部署在不同的机器上，需要修改 webapps/manager/META-INF/context.xml 配置，把下面的部分注释掉。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​Valve className=&quot;org.apache.catalina.valves.RemoteAddrValve&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        allow=&quot;127\\.\\d+\\.\\d+\\.\\d+|::1|0:0:0:0:0:0:0:1&quot; /&gt;</span></span></code></pre></div><p>xml 的注释使用 ，所以，最终注释之后变成下面这样。</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!--</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;​Valve className=&quot;org.apache.catalina.valves.RemoteAddrValve&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        allow=&quot;127\\.\\d+\\.\\d+\\.\\d+|::1|0:0:0:0:0:0:0:1&quot; /&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">--&gt;</span></span></code></pre></div><p>然后修改 Tomcat 的 rule.toml，写上认证信息，即可测试。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins tomcat</span></span></code></pre></div><p>Tomcat 的仪表盘暂未整理，欢迎你来贡献 PR 呀。</p><h3 id="cprobe-监控-kafka" tabindex="-1">Cprobe 监控 Kafka <a class="header-anchor" href="#cprobe-监控-kafka" aria-label="Permalink to &quot;Cprobe 监控 Kafka&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kafka 的众多指标是通过 jmx 的方式暴露的，所以，在 Kafka 启动的 shell 里通过  -</span></span>
<span class="line"><span>javaagent  埋入  prometheus_jmx_agent.jar ，就可以暴露 Prometheus 协议的监控</span></span></code></pre></div><p>数据了，使用 Cprobe 的 Prometheus 插件来抓即可。但是 Cprobe 还是提供了一个专门的Kafka 插件，用于抓取 consumergroup 的 lag 信息，配置文件在 conf.d/kafka 目录下，main.yaml 内容举例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span>
<span class="line"><span>   cplugin: &#39;kafka&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;kafka&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - &#39;10.99.1.105:9092&#39;</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule.toml&#39;</span></span></code></pre></div><p>如果是监控集群，想要写多个实例，Kafka 的 target 写法跟其他的 plugin 会有不同，如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span>
<span class="line"><span>   cplugin: &#39;kafka&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span> - job_name: &#39;kafka&#39;</span></span>
<span class="line"><span>   static_configs:</span></span>
<span class="line"><span>     - targets:</span></span>
<span class="line"><span>         - &#39;172.21.0.162:9092,172.21.0.163:9092,172.21.0.164:9092&#39;</span></span>
<span class="line"><span>   scrape_rule_files:</span></span>
<span class="line"><span>     - &#39;rule.toml&#39;</span></span></code></pre></div><p>和 mysql 插件对比一下，应该可以看出差别吧？你知道为啥会有这样的不同设计么？欢迎在评论区留言探讨 😃</p><p>可以通过如下面命令可以测试是否采集成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins kafka</span></span></code></pre></div><p>只要输出一堆 Kafka 指标就说明采集正常，重启 Cprobe 稍等片刻就可以在时序库查到 Kafka相关的监控数据了，仪表盘样例如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/7.png" alt=""></a></p><h3 id="cprobe-监控-elasticsearch" tabindex="-1">Cprobe 监控 ElasticSearch <a class="header-anchor" href="#cprobe-监控-elasticsearch" aria-label="Permalink to &quot;Cprobe 监控 ElasticSearch&quot;">​</a></h3><p>ElasticSearch 的监控插件配置在 conf.d/elasticsearch 目录下，main.yaml 举例如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>global:</span></span>
<span class="line"><span> scrape_interval: 15s</span></span>
<span class="line"><span> external_labels:</span></span>
<span class="line"><span>   cplugin: &#39;elasticsearch&#39;</span></span>
<span class="line"><span>scrape_configs:</span></span>
<span class="line"><span>- job_name: &#39;elasticsearch&#39;</span></span>
<span class="line"><span> static_configs:</span></span>
<span class="line"><span> - targets:</span></span>
<span class="line"><span>   - 10.99.1.105:9200</span></span>
<span class="line"><span> scrape_rule_files:</span></span>
<span class="line"><span> - &#39;rule.toml&#39;</span></span></code></pre></div><p>通过如下面命令可以测试是否采集成功。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./cprobe --no-writer --no-httpd --plugins elasticsearch</span></span></code></pre></div><p>只要输出一堆 ElasticSearch 指标就说明采集正常，重启 Cprobe 稍等片刻就可以在时序库查到 ElasticSearch 相关的监控数据了，仪表盘样例如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/8.png" alt=""></a></p><p>常用的插件就介绍到这里，下面对本节内容做一个小结。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Prometheus 生态使用各式各样的 Exporter 采集监控数据，但是 Exporter 比较零散难以管理，配置方式、日志打印、设计模式都不尽相同，所以我写了一个 Cprobe 的小项目，用于解决这些问题。然后我对 Cprobe 做了简介，讲解了如何安装以及常用插件的配置，希望对你有所帮助。</p><p>本节内容整理了一个脑图如下，供你参考记忆。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%BF%90%E7%BB%B4%E7%9B%91%E6%8E%A7%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/%25E5%258A%25A0%25E9%25A4%2590-Exporter%25E7%2594%259F%25E6%2580%2581%25E5%25A4%25AA%25E8%25BF%2587%25E9%259B%25B6%25E6%2595%25A3%25EF%25BC%258C%25E5%25A6%2582%25E4%25BD%2595%25E6%2595%25B4%25E5%2590%2588%25EF%25BC%259F/9.png" alt=""></a></p>`,122)])])}const g=a(t,[["render",l]]);export{d as __pageData,g as default};
